pattern.verified_toad_code:
>bgDeep = #050811;
>neonCyan = #00f5a0;
>neonBlue = #00d9f5;

canvas "Poster" {
  width: 1080px;
  height: 1350px;
  background: >bgDeep;
  font-family: "Inter, sans-serif";
}

// Center stop alpha >= 0.25 guarantees vibrant sRGB emission
rect #glowPrimary {
  at: (300px, -100px);
  size: 700px 700px;
  fill: radial-gradient(center, alpha(>neonBlue, 0.35) 0%, transparent 70%);
  filter: blur(80px);
}

rect #glowSecondary {
  at: (-150px, 400px);
  size: 800px 800px;
  fill: radial-gradient(center, alpha(>neonCyan, 0.30) 0%, transparent 75%);
  filter: blur(90px);
}
